        reply = self.connect(conversation, "failed: The print host test had no answer from http://192.168.1.50 after 30 seconds.")
        if reply is None:
            return False, "NO CARD"
        reply = last_reply(conversation, "Leave it for now")
        return self.end(reply, "failed, left")

