4679	    // --- A real printer, a live model (--printer-live-p1s) ------------------
4680	    //
4681	    // The person of 2026-10-31, against their real P1S in cloud mode: asks to
4682	    // connect it, gives its address, and asks what to do. Every message, tool
4683	    // call and note is printed once as it settles, with the seconds since the
4684	    // chat opened.
4685	
4686	    std::chrono::steady_clock::time_point                m_p1s_start;
4687	    std::optional<std::chrono::steady_clock::time_point> m_p1s_first_status;
4688	    std::optional<std::chrono::steady_clock::time_point> m_p1s_quiet_since;
4689	    std::vector<std::string>                             m_p1s_printed;
4690	    wxString                                             m_p1s_dialog;
4691	    std::size_t                                          m_p1s_tools_started{0};
4692	    std::size_t                                          m_p1s_tools_finished{0};
4693	    bool                                                 m_p1s_address_given{false};
4694	
4695	    std::string p1s_stamp() const
4696	    {
4697	        return "HARNESS LIVE +" +
4698	               std::to_string(std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - m_p1s_start).count()) + "s ";
4699	    }
4700	
4701	    void p1s_watch()
4702	    {
4703	        for (const Agent::ConversationMessage& message : live_messages()) {
4704	            if (message.state == Agent::MessageState::Streaming ||
4705	                std::find(m_p1s_printed.begin(), m_p1s_printed.end(), message.id) != m_p1s_printed.end())
4706	                continue;
4707	            m_p1s_printed.push_back(message.id);
4708	            const char* who = message.role == Agent::MessageRole::User ? "person" :
4709	                              message.role == Agent::MessageRole::Note ? "app note" :
4710	                                                                         "model";
4711	            std::cerr << p1s_stamp() << who << ": " << message.text << '\n';
4712	            if (message.error)
4713	                std::cerr << p1s_stamp() << who << " error: " << message.error->code << ' ' << message.error->message << '\n';
4714	        }
4715	        m_live_printed = live_messages().size();
4716	        // OrcaSlicer's own info dialog, which upstream's local-connect handler
4717	        // shows on a failed connection whoever asked for it.
4718	        const wxString shown = wxGetApp().get_inf_dialog_contect();
4719	        if (shown != m_p1s_dialog) {
4720	            m_p1s_dialog = shown;
4721	            if (!shown.empty())
4722	                std::cerr << p1s_stamp() << "upstream dialog shown: " << shown.ToUTF8().data() << '\n';
4723	        }
4724	        const auto& activities = live_activities();
4725	        for (; m_p1s_tools_started < activities.size(); ++m_p1s_tools_started) {
4726	            const Agent::ToolActivity& activity = activities[m_p1s_tools_started];
4727	            std::cerr << p1s_stamp() << "tool call: " << activity.tool << ' ' << activity.arguments_json << '\n';
4728	            if (activity.tool == "printer_connection_status" && !m_p1s_first_status)
4729	                m_p1s_first_status = std::chrono::steady_clock::now();
4730	        }
4731	        for (; m_p1s_tools_finished < activities.size() && activities[m_p1s_tools_finished].state != Agent::ToolState::Running; ++m_p1s_tools_finished) {
4732	            const Agent::ToolActivity& activity = activities[m_p1s_tools_finished];
4733	            std::cerr << p1s_stamp() << "tool result: " << activity.tool << " (" << tool_state_label(activity.state) << ") "
4734	                      << (activity.error ? activity.error->code + ": " + activity.error->message : activity.result_json) << '\n';
4735	        }
4736	    }
4737	
4738	    // Nothing running for three seconds: a tool's result, or a note, can start
4739	    // the next request just after the last one ended.
4740	    bool p1s_quiet()
4741	    {
4742	        p1s_watch();
4743	        const auto        messages = live_messages();
4744	        const bool        failed   = !messages.empty() && messages.back().role == Agent::MessageRole::Assistant &&
4745	                            messages.back().state == Agent::MessageState::Failed;
4746	        Agent::AgentHost* host     = live_panel()->host();
4747	        if (!live_settled() && !(failed && host != nullptr && !host->stream_active())) {
4748	            m_p1s_quiet_since.reset();
4749	            return false;
4750	        }
4751	        const auto now = std::chrono::steady_clock::now();
4752	        if (!m_p1s_quiet_since)
4753	            m_p1s_quiet_since = now;
4754	        return now - *m_p1s_quiet_since >= std::chrono::seconds(3);
4755	    }
4756	
4757	    // The app has told the model about the printer, by a note or a status read.
4758	    bool p1s_printer_reported() const
4759	    {
4760	        const std::string& address = m_state->network_check_address;
4761	        for (const Agent::ConversationMessage& message : live_messages())
4762	            if (message.role == Agent::MessageRole::Note && message.text.find(address) != std::string::npos)
4763	                return true;
4764	        for (const Agent::ToolActivity* call : live_calls("printer_connection_status"))
4765	            if (call->result_json.find(address) != std::string::npos)
4766	                return true;
4767	        return false;
4768	    }
4769	
4770	    // At least 20 seconds after the search began, with the model done answering
4771	    // whatever the app reported. A printer that stays silent ends this at two
4772	    // minutes, what --printer-network-check allows it.
4773	    bool p1s_after_the_search()
4774	    {
4775	        using namespace std::chrono_literals;
4776	        const bool quiet = p1s_quiet();
4777	        if (!m_p1s_first_status)
4778	            return quiet;
4779	        const auto waited = std::chrono::steady_clock::now() - *m_p1s_first_status;
4780	        return quiet && waited >= 20s && (waited >= 120s || p1s_printer_reported());
4781	    }
4782	
4783	    bool p1s_asked_for_the_address() const
4784	    {
4785	        const auto messages = live_messages();
4786	        return !messages.empty() && messages.back().role == Agent::MessageRole::Assistant &&
4787	               messages.back().text.find('?') != std::string::npos && mentions(messages.back().text, {"address", " ip"});
4788	    }
4789	
4790	    // What the model said once the app had told it about the printer: after the
4791	    // note naming the address, or else its answer to the last line.
4792	    std::vector<std::string> p1s_replies_after_the_report() const
4793	    {
4794	        const auto         messages = live_messages();
4795	        const std::string& address  = m_state->network_check_address;
4796	        auto               from     = std::find_if(messages.begin(), messages.end(), [&address](const Agent::ConversationMessage& message) {
4797	            return message.role == Agent::MessageRole::Note && message.text.find(address) != std::string::npos;
4798	        });
4799	        if (from == messages.end())
4800	            from = std::find_if(messages.rbegin(), messages.rend(), [](const Agent::ConversationMessage& message) {
4801	                       return message.role == Agent::MessageRole::User;
4802	                   }).base();
4803	        std::vector<std::string> replies;
4804	        for (; from != messages.end(); ++from)
4805	            if (from->role == Agent::MessageRole::Assistant && !from->text.empty())
4806	                replies.push_back(from->text);
4807	        return replies;
4808	    }
