                              {"input_schema", std::move(schema)},
                              {"strict", strict}});
     }
+    // Experiment (branch claude/connect-web-search): web search as the only
+    // added knowledge in the printer chat. Direct calls only, so no code
+    // execution blocks or containers come back to be replayed.
+    if (std::getenv("JUSPRIN_TEST_WEB_SEARCH") != nullptr)
+        items.push_back(json{{"type", "web_search_20250305"}, {"name", "web_search"}, {"max_uses", 5}});
     // Tools render first, so one breakpoint on the last caches them all.
     if (!items.empty())
         items.back()["cache_control"] = ephemeral();
@@ -218,6 +226,32 @@ std::vector<Message> conversation(const TurnTranscript& transcript, bool clears)
     return messages;
 }

+// Experiment: one line per response, for the report on the searches. Holds no
+// encrypted result content, only what was searched, found and cited.
+void log_response(const json& blocks, const json& first_usage, const json& last_usage, const std::string& stop_reason, long long elapsed_ms)
+{
+    const char* path = std::getenv("JUSPRIN_TEST_WEB_SEARCH_LOG");
+    if (path == nullptr)
+        return;
+    json summary = json::array();
+    for (const json& block : blocks) {
+        const std::string type = block.value("type", "");
+        if (type == "web_search_tool_result" && block.contains("content") && block["content"].is_array()) {
+            json results = json::array();
+            for (const json& result : block["content"])
+                results.push_back(json{{"url", result.value("url", "")}, {"title", result.value("title", "")}, {"page_age", result.value("page_age", json())}});
+            summary.push_back(json{{"type", type}, {"results", std::move(results)}});
+        } else if (type == "text") {
+            summary.push_back(json{{"type", type}, {"text", block.value("text", "")}, {"citations", block.value("citations", json())}});
+        } else if (type == "server_tool_use" || type == "tool_use") {
+            summary.push_back(json{{"type", type}, {"name", block.value("name", "")}, {"input", block.value("input", json())}});
+        } else if (type != "thinking" && type != "redacted_thinking") {
+            summary.push_back(block);
+        }
+    }
+    std::ofstream(path, std::ios::app) << json{{"stop_reason", stop_reason}, {"elapsed_ms", elapsed_ms}, {"usage_start", first_usage}, {"usage_end", last_usage}, {"blocks", std::move(summary)}}.dump() << '\n';
+}
+
